-- Update 21: menu block = two dish photos (left) + text (right); "Cocktails" activity card gets the passion-fruit cocktail
UPDATE "site_content" SET "data" = ("data" - 'cardKicker' - 'cardTitle' - 'highlights' - 'cardNote') || '{"image1": "/images/ig/menu-steak.webp", "image2": "/images/ig/menu-fish.webp"}'::jsonb WHERE "key" = 'home.menu' AND COALESCE("data"->>'image1', '') = '';--> statement-breakpoint
UPDATE "site_content" SET "data" = jsonb_set("data", '{polaroids}', (SELECT jsonb_agg(CASE WHEN e->>'image' = '/images/ig/cocktail-passion.webp' THEN e || '{"image": "/images/ig/activity-cocktail.webp"}'::jsonb ELSE e END ORDER BY o) FROM jsonb_array_elements("data"->'polaroids') WITH ORDINALITY AS t(e, o))) WHERE "key" = 'home.activities' AND jsonb_typeof("data"->'polaroids') = 'array' AND jsonb_array_length("data"->'polaroids') > 0;
